{
  "python": "def pilot_policy(trace):
    action, label = trace[-1]
    cats = label.subset
    args = json.loads(action.arguments)
    name = action.name
    forbidden = {
        "slot:audit": {"SOURCE", "CREDENTIAL"},
        "slot:marketplace": {"CUSTOMER", "CREDENTIAL"},
        "slot:production": {"UNVERIFIED"},
        "slot:public": {"CUSTOMER", "SOURCE", "CREDENTIAL"},
        "slot:vendor": {"SOURCE", "CREDENTIAL"}
    }
    if name == "builder/import_component":
        pass
    elif name == "reviewer/review_component":
        pass
    elif name == "release_bot/assemble_build":
        pass
    elif name in ("release/deliver_build", "operations/deliver_build"):
        channel = args.get("channel")
        telemetry = args.get("telemetry")
        agent = "release" if name == "release/deliver_build" else "operations"
        if agent == "release":
            slot_map = {"local": "slot:internal", "partner": "slot:marketplace", "release": "slot:public"}
        else:
            slot_map = {"local": "slot:internal", "partner": "slot:vendor", "release": "slot:production"}
        slots = {slot_map[channel]}
        if telemetry == "audit":
            slots.add("slot:audit")
        elif telemetry == "partner":
            slots.add(slot_map[channel])
        elif telemetry == "public":
            slots.add("slot:public")
        if any(cat in forbidden[slot] for slot in slots for cat in cats if slot in forbidden):
            raise PolicyViolation("Deliver build writes forbidden categories to restricted slot")
    else:
        raise PolicyViolation("Unknown action")"
}
